package io.tornnote;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class TornNoteTest{@Test void bothBackends()throws Exception{for(String c:List.of("ed25519","p256")){var m=TornNote.keys(c);var ns=new ArrayList<TornNote.Note>();for(int i=0;i<8;i++)ns.add(new TornNote.Note(("note-"+i).getBytes(),TornNote.keys(c),TornNote.keys(c)));var ls=new ArrayList<byte[]>();for(var n:ns)ls.add(TornNote.leaf(n.id(),TornNote.pub(n.a().pair()),TornNote.pub(n.b().pair())));var r=TornNote.root(ls);var n=ns.get(3);var pr=TornNote.proof(ls,3);var a=TornNote.pub(n.a().pair()),b=TornNote.pub(n.b().pair());var s=TornNote.authorize(m,n.a(),n.b(),r,n.id(),a,b,"amount=42&currency=EUR",pr,3);assertTrue(TornNote.verifyAuthorization(m.pair().getPublic(),n.a().pair().getPublic(),n.b().pair().getPublic(),r,n.id(),a,b,"amount=42&currency=EUR",pr,3,s,false));assertFalse(TornNote.verifyAuthorization(m.pair().getPublic(),n.a().pair().getPublic(),n.b().pair().getPublic(),r,n.id(),a,b,"amount=43&currency=EUR",pr,3,s,false));assertFalse(TornNote.verifyAuthorization(m.pair().getPublic(),n.a().pair().getPublic(),n.b().pair().getPublic(),r,n.id(),a,b,"amount=42&currency=EUR",pr,3,s,true));}}}